let cfVarBase=null,cfVarComp=null;
function cfVarPeriodSelectors(){
  const opts=PERIODOS.filter(p=>ER[p]);
  if(opts.length<2){document.getElementById("cf-var-base").innerHTML="";document.getElementById("cf-var-comp").innerHTML="";return;}
  const sel=getCmpPeriodos().filter(p=>ER[p]);
  const baseDefault=sel.length?sel[0]:opts[0];
  const compDefault=sel.length>1?sel[sel.length-1]:opts[opts.length-1];
  if(!cfVarBase||!opts.includes(cfVarBase)) cfVarBase=baseDefault;
  if(!cfVarComp||!opts.includes(cfVarComp)) cfVarComp=compDefault;
  const html=opts.map(p=>`<option value="${p}">${P.periodos_label[p]}</option>`).join("");
  document.getElementById("cf-var-base").innerHTML=html;
  document.getElementById("cf-var-comp").innerHTML=html;
  document.getElementById("cf-var-base").value=cfVarBase;
  document.getElementById("cf-var-comp").value=cfVarComp;
}
let cfVarItemsSort={dir:-1};
function cfVarItems(){
  const base=cfVarBase,comp=cfVarComp;
  const el=document.getElementById("cf-var-items");
  if(!base||!comp||base===comp||!ER[base]||!ER[comp]){el.innerHTML="<thead></thead><tbody><tr><td style='padding:14px;color:var(--muted)'>Elegi dos periodos distintos para comparar.</td></tr></tbody>";return;}
  const ab={},ac={};
  (ER[base].costos_fijos_items||[]).forEach(it=>ab[it.label]=it.total);
  (ER[comp].costos_fijos_items||[]).forEach(it=>ac[it.label]=it.total);
  const keys=new Set([...Object.keys(ab),...Object.keys(ac)]);
  let rows=[...keys].map(lab=>{const a=ab[lab]||0,b=ac[lab]||0;return {lab,a,b,diff:b-a};});
  rows=rows.sort((x,y)=>(Math.abs(y.diff)-Math.abs(x.diff))*(cfVarItemsSort.dir===-1?1:-1));
  let h=`<thead><tr><th>Item</th><th class="right">${P.periodos_short[base]}</th><th class="right">${P.periodos_short[comp]}</th><th class="right sortable" data-sort="diff">Diferencia $</th><th class="right">Diferencia %</th></tr></thead><tbody>`;
  rows.forEach(r=>{h+=`<tr><td style="font-weight:600">${r.lab}</td><td class="right">${fmtMoneyShort(r.a)}</td><td class="right">${fmtMoneyShort(r.b)}</td>${cpVarDiffCell(r.diff,r.a)}</tr>`;});
  el.innerHTML=h+"</tbody>";
  bindSortHeader(el,cfVarItemsSort,cfVarItems);
}

