let heatmapOsSel=null; // Set de OS visibles en el heatmap (null = todas)
let lastHeatmapPeriodo=null;
function cpHeatmapFilters(allOs){
  if(heatmapOsSel===null) heatmapOsSel=new Set(allOs);
  document.getElementById("heatmap-os-filters").innerHTML = allOs.map(o=>
    `<label class="hm-chip"><input type="checkbox" data-os="${o}" ${heatmapOsSel.has(o)?"checked":""}> ${o}</label>`
  ).join("");
  document.querySelectorAll("#heatmap-os-filters input").forEach(cb=>cb.addEventListener("change",e=>{
    const o=e.target.dataset.os;
    if(e.target.checked) heatmapOsSel.add(o); else heatmapOsSel.delete(o);
    if(lastHeatmapPeriodo) cpHeatmap(lastHeatmapPeriodo);
  }));
}
function cpHeatmap(periodo){
  lastHeatmapPeriodo=periodo;
  const m=CP[periodo];const cats=m.categorias.map(c=>c.cat);const allOs=m.obras_sociales.map(o=>o.os);
  cpHeatmapFilters(allOs);
  const oss=allOs.filter(o=>heatmapOsSel.has(o));
  const totalGeneral=m.totals.ap_total||0;
  const colorFor=(v,maxRow)=>{if(!v)return null;const r=v/maxRow;return `hsl(${220-r*30}, 75%, ${75-r*40}%)`;};
  let h=`<thead><tr><th style="text-align:left">Categoria</th>${oss.map(o=>`<th>${o}</th>`).join('')}<th>Total</th></tr></thead><tbody>`;
  cats.forEach(c=>{
    let tot=0,maxRow=0;
    oss.forEach(o=>{const v=(m.heatmap[c]||{})[o]||0;if(v>maxRow)maxRow=v;});
    h+=`<tr><td class="label">${c}</td>`;
    oss.forEach(o=>{
      const v=(m.heatmap[c]||{})[o]||0;tot+=v;
      if(v){
        const pctTotal=totalGeneral?(v/totalGeneral*100).toFixed(1).replace('.',','):"0";
        h+=`<td style="background:${colorFor(v,maxRow)}" title="${fmtMoneyFull(v)} (${pctTotal}% del total)">${fmtMoneyShort(v)}</td>`;
      } else {
        h+=`<td class="zero" title="$ 0,00">$0</td>`;
      }
    });
    h+=`<td style="background:#0A1F8C" title="${fmtMoneyFull(tot)}">${fmtMoneyShort(tot)}</td></tr>`;
  });
  h+=`<tr><td class="label" style="background:#EEF2FB">TOTAL</td>`;let grand=0;
  oss.forEach(o=>{const ct=cats.reduce((s,c)=>s+((m.heatmap[c]||{})[o]||0),0);grand+=ct;h+=`<td style="background:#0A1F8C" title="${fmtMoneyFull(ct)}">${fmtMoneyShort(ct)}</td>`;});
  h+=`<td style="background:#06146A" title="${fmtMoneyFull(grand)}">${fmtMoneyShort(grand)}</td></tr></tbody>`;
  document.getElementById("cp-heatmap").innerHTML=h;
}
function cpTop(periodo){
