function cpCmpGetTotals(p, osFilter){
  if(!CP[p]) return null;
  if(!osFilter) return CP[p].totals;
  // Calcular totales filtrados por OS desde invoices
  const invs=CP[p].invoices.filter(i=>i.os===osFilter);
  if(!invs.length) return {ap_total:0,ft_total:0,da_total:0,dm_total:0,n_facturas:0,n_prestadores:0,factura_promedio:0};
  const ap=invs.reduce((s,i)=>s+i.ap,0);
  const ft=invs.reduce((s,i)=>s+i.ft,0);
  const da=invs.reduce((s,i)=>s+i.da,0);
  const dm=invs.reduce((s,i)=>s+i.dm,0);
  const prest=new Set(invs.map(i=>i.p)).size;
  return {ap_total:ap,ft_total:ft,da_total:da,dm_total:dm,n_facturas:invs.length,n_prestadores:prest,factura_promedio:invs.length?ft/invs.length:0};
}
