  const fc=document.getElementById("cp-cmp-filter-cat").value;
  document.getElementById("cp-cmp-filter-os").innerHTML=`<option value="">Todas las OS</option>`+oss.map(o=>`<option value="${o}">${o}</option>`).join('');
  document.getElementById("cp-cmp-filter-cat").innerHTML=`<option value="">Todas las categorias</option>`+cats.map(c=>`<option value="${c}">${c}</option>`).join('');
  if(oss.includes(fo)) document.getElementById("cp-cmp-filter-os").value=fo;
  if(cats.includes(fc)) document.getElementById("cp-cmp-filter-cat").value=fc;
}
let cpCmpInvSort={key:"ap",dir:-1};
function cpCmpInvoiceTable(){
  const sel=getCmpPeriodos().filter(p=>CP[p]);
  const s=(document.getElementById("cp-cmp-search").value||"").toLowerCase();
  const fo=document.getElementById("cp-cmp-filter-os").value;
  const fc=document.getElementById("cp-cmp-filter-cat").value;
  let all=[];
  sel.forEach(p=>{CP[p].invoices.forEach(i=>all.push(Object.assign({periodo:p},i)));});
  let filt=all.filter(i=>{if(fo&&i.os!==fo)return false;if(fc&&i.cat!==fc)return false;if(s&&!(`${i.p} ${i.f}`.toLowerCase().includes(s)))return false;return true;});
  const k=cpCmpInvSort.key,d=cpCmpInvSort.dir;
  filt=filt.sort((a,b)=>((a[k]||0)-(b[k]||0))*d);
  document.getElementById("cp-cmp-inv-count").textContent=`- ${filt.length} de ${all.length} facturas`;
  document.getElementById("cp-cmp-inv-body").innerHTML=filt.slice(0,500).map(i=>{const dt=i.da+i.dm;return `<tr><td>${P.periodos_short[i.periodo]}</td><td style="font-weight:600">${i.p}</td><td>${i.f}</td><td>${i.fp||"-"}</td><td>${i.pe||"-"}</td><td><span class="cat-tag" style="background:${(CAT_COLOR[i.cat]||"#999")}22;color:${CAT_COLOR[i.cat]||"#666"}">${i.cat}</span></td><td><span class="os-tag" style="background:${OS_COLOR[i.os]||"#999"}22;color:${OS_COLOR[i.os]||"#666"}">${i.os||"-"}</span></td><td class="right">${i.plr!==null?i.plr+"d":"-"}</td><td class="right">${fmtMoneyShort(i.ft)}</td><td class="right">${dt>0?fmtMoneyShort(dt):"-"}</td><td class="right"><strong>${fmtMoneyShort(i.ap)}</strong></td></tr>`;}).join("");
  document.querySelectorAll("#cp-cmp-inv-table thead th.sortable").forEach(th=>{
    th.querySelectorAll(".sort-arrow").forEach(a=>a.remove());
    if(th.dataset.sort===k) th.insertAdjacentHTML("beforeend",`<span class="sort-arrow">${d===-1?"▼":"▲"}</span>`);
  });
}
function bindSortHeader(el,state,renderFn){
  const th=el.querySelector("th.sortable");
  if(!th)return;
  th.querySelectorAll(".sort-arrow").forEach(a=>a.remove());
  th.insertAdjacentHTML("beforeend",`<span class="sort-arrow">${state.dir===-1?"▼":"▲"}</span>`);
  th.addEventListener("click",()=>{state.dir*=-1;renderFn();});
}
function cpVarDiffCell(diff,base){
  const pct=base?(diff/Math.abs(base))*100:(diff?100:0);
  const cls=diff>0?"delta-pos-cell":(diff<0?"delta-neg-cell":"");
  const sign=diff>0?"+":"";
  return `<td class="right ${cls}">${sign}${fmtMoneyShort(diff)}</td><td class="right ${cls}">${sign}${pct.toFixed(1).replace('.',',')}%</td>`;
}
let cpVarBase=null,cpVarComp=null;
function cpVarPeriodSelectors(){
  const opts=PERIODOS.filter(p=>CP[p]);
  if(opts.length<2){document.getElementById("cp-var-base").innerHTML="";document.getElementById("cp-var-comp").innerHTML="";return;}
  const sel=getCmpPeriodos().filter(p=>CP[p]);
  const baseDefault=sel.length?sel[0]:opts[0];
  const compDefault=sel.length>1?sel[sel.length-1]:opts[opts.length-1];
  if(!cpVarBase||!opts.includes(cpVarBase)) cpVarBase=baseDefault;
  if(!cpVarComp||!opts.includes(cpVarComp)) cpVarComp=compDefault;
  const html=opts.map(p=>`<option value="${p}">${P.periodos_label[p]}</option>`).join("");
  document.getElementById("cp-var-base").innerHTML=html;
  document.getElementById("cp-var-comp").innerHTML=html;
  document.getElementById("cp-var-base").value=cpVarBase;
  document.getElementById("cp-var-comp").value=cpVarComp;
}
let cpVarCatosSort={dir:-1};
function cpVarCatOs(){
  const base=cpVarBase,comp=cpVarComp;
  const el=document.getElementById("cp-var-catos");
  if(!base||!comp||base===comp){el.innerHTML="<thead></thead><tbody><tr><td style='padding:14px;color:var(--muted)'>Elegi dos periodos distintos para comparar.</td></tr></tbody>";return;}
  const agg=(p)=>{const m={};CP[p].invoices.forEach(i=>{const k=i.cat+"|"+i.os;m[k]=(m[k]||0)+i.ap;});return m;};
  const ab=agg(base),ac=agg(comp);
  const keys=new Set([...Object.keys(ab),...Object.keys(ac)]);
  let rows=[...keys].map(k=>{const [cat,os]=k.split("|");const a=ab[k]||0,b=ac[k]||0;return {cat,os,a,b,diff:b-a};});
  rows=rows.sort((x,y)=>(Math.abs(y.diff)-Math.abs(x.diff))*(cpVarCatosSort.dir===-1?1:-1));
  let h=`<thead><tr><th>Categoria</th><th>OS</th><th class="right">${P.periodos_short[base]}</th><th class="right">${P.periodos_short[comp]}</th><th class="right sortable" data-sort="diff">Diferencia $</th><th class="right">Diferencia %</th></tr></thead><tbody>`;
  rows.forEach(r=>{h+=`<tr><td><span class="cat-tag" style="background:${(CAT_COLOR[r.cat]||"#999")}22;color:${CAT_COLOR[r.cat]||"#666"}">${r.cat}</span></td><td><span class="os-tag" style="background:${OS_COLOR[r.os]||"#999"}22;color:${OS_COLOR[r.os]||"#666"}">${r.os}</span></td><td class="right">${fmtMoneyShort(r.a)}</td><td class="right">${fmtMoneyShort(r.b)}</td>${cpVarDiffCell(r.diff,r.a)}</tr>`;});
  el.innerHTML=h+"</tbody>";
  bindSortHeader(el,cpVarCatosSort,cpVarCatOs);
}
let cpVarPrestSort={dir:-1};
function cpVarPrestadores(){
  const base=cpVarBase,comp=cpVarComp;
  const el=document.getElementById("cp-var-prest");
  if(!base||!comp||base===comp){el.innerHTML="<thead></thead><tbody><tr><td style='padding:14px;color:var(--muted)'>Elegi dos periodos distintos para comparar.</td></tr></tbody>";return;}
  const agg=(p)=>{const m={};CP[p].invoices.forEach(i=>{m[i.p]=(m[i.p]||0)+i.ap;});return m;};
  const ab=agg(base),ac=agg(comp);
  const keys=new Set([...Object.keys(ab),...Object.keys(ac)]);
  let rows=[...keys].map(p=>{const a=ab[p]||0,b=ac[p]||0;return {p,a,b,diff:b-a};});
  rows=rows.sort((x,y)=>(Math.abs(y.diff)-Math.abs(x.diff))*(cpVarPrestSort.dir===-1?1:-1));
  let h=`<thead><tr><th>Prestador</th><th class="right">${P.periodos_short[base]}</th><th class="right">${P.periodos_short[comp]}</th><th class="right sortable" data-sort="diff">Diferencia $</th><th class="right">Diferencia %</th></tr></thead><tbody>`;
  rows.forEach(r=>{h+=`<tr><td style="font-weight:600">${r.p}</td><td class="right">${fmtMoneyShort(r.a)}</td><td class="right">${fmtMoneyShort(r.b)}</td>${cpVarDiffCell(r.diff,r.a)}</tr>`;});
  el.innerHTML=h+"</tbody>";
  bindSortHeader(el,cpVarPrestSort,cpVarPrestadores);
}
let cpVarAltasSort={dir:-1};
function cpVarAltas(){
  const base=cpVarBase,comp=cpVarComp;
  const el=document.getElementById("cp-var-altas");
  if(!base||!comp||base===comp){el.innerHTML="<thead></thead><tbody><tr><td style='padding:14px;color:var(--muted)'>Elegi dos periodos distintos para comparar.</td></tr></tbody>";return;}
  const agg=(p)=>{const m={};CP[p].invoices.forEach(i=>{m[i.p]=(m[i.p]||0)+i.ap;});return m;};
  const ab=agg(base),ac=agg(comp);
  let rows=[];
  Object.keys(ac).forEach(p=>{if(!(p in ab)) rows.push({p,estado:"Nueva",periodo:comp,monto:ac[p]});});
  Object.keys(ab).forEach(p=>{if(!(p in ac)) rows.push({p,estado:"Desaparecida",periodo:base,monto:ab[p]});});
  if(!rows.length){el.innerHTML="<thead></thead><tbody><tr><td style='padding:14px;color:var(--muted)'>No hay prestadores nuevos ni desaparecidos entre estos periodos.</td></tr></tbody>";return;}
  rows=rows.sort((x,y)=>(y.monto-x.monto)*(cpVarAltasSort.dir===-1?1:-1));
  let h=`<thead><tr><th>Prestador</th><th>Estado</th><th>Periodo</th><th class="right sortable" data-sort="monto">Monto</th></tr></thead><tbody>`;
  rows.forEach(r=>{const cls=r.estado==="Nueva"?"pill-pos":"pill-neg";h+=`<tr><td style="font-weight:600">${r.p}</td><td><span class="${cls}">${r.estado}</span></td><td>${P.periodos_short[r.periodo]}</td><td class="right">${fmtMoneyShort(r.monto)}</td></tr>`;});
  el.innerHTML=h+"</tbody>";
  bindSortHeader(el,cpVarAltasSort,cpVarAltas);
}

// ===== INGRESOS =====
let ingCurrentPeriodo=null;
let ingVarBase=null,ingVarComp=null;
const ING_ROWS=[
  {key:"afiliados",      label:"Afiliados",              fmt:"num",  bold:false},
  {key:"capita_unit",    label:"Capita Unitaria ($)",     fmt:"money",bold:false},
  {key:"subtotal_capita",label:"Subtotal Capita",         fmt:"mshort",bold:false},
  {key:"refuerzo_capita",label:"Refuerzo Capita",         fmt:"mshort",bold:false},
  {key:"notas_credito",  label:"NC / ND",                fmt:"mshort",bold:false},
  {key:"ingresos_extras",label:"Otros Servicios",         fmt:"mshort",bold:false},
  {key:"extracapita_ingreso",label:"Extracapita",         fmt:"mshort",bold:false},
  {key:"ingresos_netos", label:"Ingresos Netos",          fmt:"mshort",bold:true},
];

function ingGetVal(data,key,osCode){
  // data = ER[p]  or  ER[p].totals
  if(osCode==="TOTAL"){
    const t=data.totals;
    if(key==="capita_unit") return null; // no aplica para total
    return t[key]||0;
  }
  const os=data.obras_sociales.find(o=>o.code===osCode);
  if(!os) return 0;
  return os[key]||0;
}

function ingBuildOsFilter(elId){
  const sel=document.getElementById(elId);
  const cur=sel.value;
  let h=`<option value="TOTAL">Total (todas las OS)</option>`;
  const osCodes=new Set();
  PERIODOS.forEach(p=>{if(ER[p]) ER[p].obras_sociales.forEach(o=>osCodes.add(o.code));});
  osCodes.forEach(c=>{ h+=`<option value="${c}" ${cur===c?"selected":""}>${c}</option>`; });
  sel.innerHTML=h;
}

function ingFmt(v,fmt){
  if(v===null||v===undefined) return "—";
  switch(fmt){
    case"num":    return fmtNum(v);
    case"money":  return fmtMoney(v);
    case"mshort": return fmtMoneyShort(v);
    default:      return v;
  }
}

function ingKpisSingle(pv){
  const d=ER[pv];if(!d){document.getElementById("ing-kpis").innerHTML="";return;}
  const t=d.totals;
  const prev=PERIODOS[PERIODOS.indexOf(pv)-1];
  const tp=prev&&ER[prev]?ER[prev].totals:null;
  function kpi(label,val,pval,fmt){
    const fv=fmt==="num"?fmtNum(val):fmtMoneyShort(val);
    let diff="";
    if(pval!=null&&pval!==0&&val!==null){
      const pct=((val-pval)/Math.abs(pval)*100);
      const sign=pct>=0?"+":"";
      diff=`<div class="kpi-delta ${pct>=0?"pos":"neg"}">${sign}${pct.toFixed(1).replace(".",",")}% vs ${P.periodos_short[prev]}</div>`;
    }
    return `<div class="kpi-card"><div class="kpi-label">${label}</div><div class="kpi-value">${fv}</div>${diff}</div>`;
  }
  let h="";
  h+=kpi("Ingresos Netos",t.ingresos_netos,tp?tp.ingresos_netos:null,"mshort");
  h+=kpi("Subtotal Capita",t.subtotal_capita,tp?tp.subtotal_capita:null,"mshort");
  h+=kpi("Extracapita",t.extracapita_ingreso||0,tp?tp.extracapita_ingreso||0:null,"mshort");
  h+=kpi("Otros Servicios",t.ingresos_extras||0,tp?tp.ingresos_extras||0:null,"mshort");
  h+=kpi("Afiliados",t.afiliados,tp?tp.afiliados:null,"num");
  document.getElementById("ing-kpis").innerHTML=h;
}

function ingTable(pv){
  const el=document.getElementById("ing-table");
  if(!ER[pv]){el.innerHTML="";return;}
  const d=ER[pv];
  const osCode=document.getElementById("ing-os-filter").value||"TOTAL";
  // columnas: concepto + valor actual + (vs mes anterior si existe)
  const prev=PERIODOS[PERIODOS.indexOf(pv)-1];
  const hasPrev=prev&&ER[prev];
  let h=`<thead><tr><th>Concepto</th><th class="right">${P.periodos_label[pv]}</th>`;
  if(hasPrev) h+=`<th class="right">${P.periodos_label[prev]}</th><th class="right">Dif. $</th><th class="right">Dif. %</th>`;
  h+=`</tr></thead><tbody>`;
  ING_ROWS.forEach(row=>{
    const val=ingGetVal(d,row.key,osCode);
    const bold=row.bold?"font-weight:700;background:var(--stripe)":"";
    if(val===null){
      h+=`<tr style="${bold}"><td>${row.label}</td><td class="right" colspan="${hasPrev?4:1}">—</td></tr>`;
      return;
    }
    let diffHtml="";
    if(hasPrev){
      const pval=ingGetVal(ER[prev],row.key,osCode);
      if(pval!==null){
        const dif=val-(pval||0);
        const pct=(pval&&pval!==0)?(dif/Math.abs(pval)*100):null;
        const cls=dif>=0?"color:#0E9F6E":"color:#E74C3C";
        const pctStr=pct!=null?`<span style="${cls}">${(dif>=0?"+":"")}${pct.toFixed(1).replace(".",",")}%</span>`:"—";
        diffHtml=`<td class="right">${fmtMoneyShort(pval)}</td><td class="right"><span style="${cls}">${dif>=0?"+":""}${fmtMoneyShort(dif)}</span></td><td class="right">${pctStr}</td>`;
      } else {diffHtml=`<td class="right">—</td><td class="right">—</td><td class="right">—</td>`;}
    }
    h+=`<tr style="${bold}"><td>${row.label}</td><td class="right">${ingFmt(val,row.fmt)}</td>${diffHtml}</tr>`;
  });
  el.innerHTML=h+"</tbody>";
}

function ingCharts(pv){
  const d=ER[pv];if(!d) return;
  const t=d.totals;
  // Grafico composicion
  destroyChart("ingComp");
  const compCtx=document.getElementById("ingChartComp").getContext("2d");
  const compData=[
    {label:"Subtotal Capita",val:t.subtotal_capita||0,color:"#0A1F8C"},
    {label:"Refuerzo Capita",val:t.refuerzo_capita||0,color:"#0BC8FA"},
    {label:"NC/ND",val:t.notas_credito||0,color:"#E74C3C"},
    {label:"Otros Servicios",val:t.ingresos_extras||0,color:"#7A52F4"},
    {label:"Extracapita",val:t.extracapita_ingreso||0,color:"#0E9F6E"},
  ].filter(x=>x.val!==0);
  charts["ingComp"]=new Chart(compCtx,{type:"doughnut",data:{labels:compData.map(x=>x.label),datasets:[{data:compData.map(x=>Math.abs(x.val)),backgroundColor:compData.map(x=>x.color)}]},options:{plugins:{legend:{position:"bottom"}},maintainAspectRatio:false}});
  // Grafico por OS
  destroyChart("ingOs");
  const osCtx=document.getElementById("ingChartOs").getContext("2d");
  const osList=d.obras_sociales;
  charts["ingOs"]=new Chart(osCtx,{type:"bar",data:{labels:osList.map(o=>o.code),datasets:[{label:"Ingresos Netos",data:osList.map(o=>o.ingresos_netos||0),backgroundColor:osList.map(o=>OS_COLOR[o.code]||"#9CA8C0")}]},options:{plugins:{legend:{display:false}},scales:{y:{ticks:{callback:v=>fmtMoneyShort(v)}}},maintainAspectRatio:false}});
}

function ingKpisCompare(){
  const sel=getCmpPeriodos();
  if(!sel.length){document.getElementById("ing-kpis").innerHTML="";return;}
  // KPI: promedio ingresos, tendencia
  let h="";
  const last=sel[sel.length-1];
  const prev=sel[sel.length-2];
  if(ER[last]){
    function kpi2(label,val,pval,fmt){
      const fv=fmt==="num"?fmtNum(val):fmtMoneyShort(val);
      let diff="";
      if(pval!=null&&pval!==0){const pct=((val-pval)/Math.abs(pval)*100);const sign=pct>=0?"+":"";diff=`<div class="kpi-delta ${pct>=0?"pos":"neg"}">${sign}${pct.toFixed(1).replace(".",",")}% vs ${P.periodos_short[prev]}</div>`;}
      return `<div class="kpi-card"><div class="kpi-label">${label}</div><div class="kpi-value">${fv}</div>${diff}</div>`;
    }
    const t=ER[last].totals,tp=prev&&ER[prev]?ER[prev].totals:null;
    h+=kpi2("Ingresos Netos",t.ingresos_netos,tp?tp.ingresos_netos:null,"mshort");
    h+=kpi2("Extracapita",t.extracapita_ingreso||0,tp?tp.extracapita_ingreso||0:null,"mshort");
    h+=kpi2("Otros Servicios",t.ingresos_extras||0,tp?tp.ingresos_extras||0:null,"mshort");
    h+=kpi2("Afiliados",t.afiliados,tp?tp.afiliados:null,"num");
  }
  document.getElementById("ing-kpis").innerHTML=h;
}

function ingTrend(){
  destroyChart("ingTrend");
  const sel=getCmpPeriodos();
  const ctx=document.getElementById("ingTrend").getContext("2d");
  const datasets=[
    {label:"Subtotal Capita",key:"subtotal_capita",color:"#0A1F8C"},
    {label:"Otros Servicios",key:"ingresos_extras",color:"#7A52F4"},
    {label:"Extracapita",key:"extracapita_ingreso",color:"#0E9F6E"},
    {label:"Refuerzo Capita",key:"refuerzo_capita",color:"#0BC8FA"},
  ];
  charts["ingTrend"]=new Chart(ctx,{type:"bar",data:{
    labels:sel.map(p=>P.periodos_short[p]),
    datasets:datasets.map(ds=>({label:ds.label,data:sel.map(p=>ER[p]?(ER[p].totals[ds.key]||0):0),backgroundColor:ds.color,stack:"s"}))
  },options:{scales:{x:{stacked:true},y:{stacked:true,ticks:{callback:v=>fmtMoneyShort(v)}}},plugins:{legend:{position:"bottom"}},maintainAspectRatio:false}});
}

function ingCmpTable(){
  const el=document.getElementById("ing-cmp-table");
  const sel=getCmpPeriodos().filter(p=>ER[p]);
  if(!sel.length){el.innerHTML="<thead></thead><tbody><tr><td style='padding:14px;color:var(--muted)'>Sin datos.</td></tr></tbody>";return;}
  const osCode=document.getElementById("ing-cmp-os-filter").value||"TOTAL";
  let h=`<thead><tr><th>Concepto</th>${sel.map(p=>`<th class="right">${P.periodos_short[p]}</th>`).join("")}</tr></thead><tbody>`;
  ING_ROWS.forEach(row=>{
    const bold=row.bold?"font-weight:700;background:var(--stripe)":"";
    const vals=sel.map(p=>ingGetVal(ER[p],row.key,osCode));
    if(vals.every(v=>v===null)){return;}
    h+=`<tr style="${bold}"><td>${row.label}</td>${vals.map((v,i)=>`<td class="right">${v===null?"—":ingFmt(v,row.fmt)}</td>`).join("")}</tr>`;
  });
  el.innerHTML=h+"</tbody>";
}

function ingVarPeriodSelectors(){
  const sel=getCmpPeriodos().filter(p=>ER[p]);
  if(sel.length<2) return;
  if(!ingVarBase||!sel.includes(ingVarBase)) ingVarBase=sel[sel.length-2];
  if(!ingVarComp||!sel.includes(ingVarComp)) ingVarComp=sel[sel.length-1];
  ["ing-var-base","ing-var-comp"].forEach((id,idx)=>{
    const el=document.getElementById(id);
    const cur=idx===0?ingVarBase:ingVarComp;
    el.innerHTML=sel.map(p=>`<option value="${p}" ${p===cur?"selected":""}>${P.periodos_label[p]}</option>`).join("");
  });
  ingVarTable();
}

function ingVarTable(){
  const el=document.getElementById("ing-var-table");
  if(!ingVarBase||!ingVarComp||!ER[ingVarBase]||!ER[ingVarComp]){el.innerHTML="<thead></thead><tbody><tr><td style='padding:14px;color:var(--muted)'>Selecciona dos periodos para comparar.</td></tr></tbody>";return;}
  const db=ER[ingVarBase],dc=ER[ingVarComp];
  // Filas: concepto + OS
  const osList=[{code:"TOTAL",label:"TOTAL"},...db.obras_sociales.map(o=>({code:o.code,label:o.code}))];
  let h=`<thead><tr><th>Concepto</th><th>OS</th><th class="right">${P.periodos_short[ingVarBase]}</th><th class="right">${P.periodos_short[ingVarComp]}</th><th class="right">Dif. $</th><th class="right">Dif. %</th></tr></thead><tbody>`;
  ING_ROWS.filter(r=>r.key!=="capita_unit"&&r.key!=="afiliados").forEach(row=>{
    osList.forEach(os=>{
      const vb=ingGetVal(db,row.key,os.code)||0;
      const vc=ingGetVal(dc,row.key,os.code)||0;
      if(vb===0&&vc===0) return;
      const dif=vc-vb;
      const pct=vb!==0?(dif/Math.abs(vb)*100):null;
      const cls=dif>=0?"color:#0E9F6E":"color:#E74C3C";
      const pctStr=pct!=null?`<span style="${cls}">${(dif>=0?"+":"")}${pct.toFixed(1).replace(".",",")}%</span>`:"—";
      const bold=row.bold?"font-weight:700":"";
      h+=`<tr style="${bold}"><td>${row.label}</td><td><span class="pill" style="background:${OS_COLOR[os.code]||"#9CA8C0"}22;color:${OS_COLOR[os.code]||"#6B7691"};border:1px solid ${OS_COLOR[os.code]||"#9CA8C0"}44">${os.label}</span></td><td class="right">${fmtMoneyShort(vb)}</td><td class="right">${fmtMoneyShort(vc)}</td><td class="right"><span style="${cls}">${(dif>=0?"+":"")}${fmtMoneyShort(dif)}</span></td><td class="right">${pctStr}</td></tr>`;
    });
  });
  el.innerHTML=h+"</tbody>";
}

// ===== ORCHESTRATION =====
function setTab(tab){
  currentTab=tab;
  document.querySelectorAll(".main-tab").forEach(b=>b.classList.toggle("active",b.dataset.tab===tab));
  document.querySelectorAll(".tab-content").forEach(el=>el.classList.toggle("active",el.id===`tab-${tab}`));
  const tabTitles={estado:"Estado de Resultado",costos:"Costos Prestacionales",fijos:"Costos Fijos",ingresos:"Ingresos"};
  document.getElementById("page-title").textContent=tabTitles[tab]||tab;
  render();
}
function setView(view){
  currentView=view;
  document.querySelectorAll(".period-btn").forEach(b=>b.classList.toggle("active",b.dataset.view===view));
  render();
}
function render(){
  const isCompare=currentView==="compare";
  const lbl=isCompare?"- Comparativo ("+getCmpPeriodos().length+" meses)":"- "+(P.periodos_label[currentView]||"");
  document.getElementById("er-period-label").textContent=lbl;
  document.getElementById("cp-period-label").textContent=lbl;
  document.getElementById("cf-period-label").textContent=lbl;
  document.getElementById("ing-period-label").textContent=lbl;
  if(isCompare) buildCmpFilters();
  if(currentTab==="estado"){
    document.getElementById("er-single").style.display=isCompare?"none":"block";
    document.getElementById("er-compare").style.display=isCompare?"block":"none";
    document.getElementById("er-kpis-compare").style.display=isCompare?"grid":"none";
    document.getElementById("er-single-kpis").style.display=isCompare?"none":"grid";
    if(isCompare){erKpisCompare();erTrends();erCmpTable();}
    else{
      if(!ER[currentView]){document.getElementById("er-single-kpis").style.display="none";document.getElementById("er-single").style.display="none";return;}
      const pv=currentView;erKpisSingle(pv);erCharts(pv);erRanking(pv);erOsCards(pv);erOspif(pv);
    }
  } else if(currentTab==="fijos"){
    document.getElementById("cf-single").style.display=isCompare?"none":"block";
    document.getElementById("cf-compare").style.display=isCompare?"block":"none";
    if(isCompare){cfKpisCompare();cfTrendItems();cfCmpTable();cfVarPeriodSelectors();cfVarItems();}
    else{
      const pv=currentView;
      if(!ER[pv]){document.getElementById("cf-kpis").innerHTML="<p style='color:var(--muted);padding:14px'>Sin datos de Costos Fijos para este mes.</p>";document.getElementById("cf-single").style.display="none";return;}
      cfKpisSingle(pv);cfItemsTable(pv);cfCharts(pv);cfComprobantesTable(pv);
    }
  } else if(currentTab==="ingresos"){
    document.getElementById("ing-single").style.display=isCompare?"none":"block";
    document.getElementById("ing-compare").style.display=isCompare?"block":"none";
    if(isCompare){ingKpisCompare();ingBuildOsFilter("ing-cmp-os-filter");ingCmpTable();ingVarPeriodSelectors();ingVarTable();ingTrend();}
    else{
      const pv=ER[currentView]?currentView:PERIODOS[PERIODOS.length-1];
      ingCurrentPeriodo=pv;
      if(!ER[pv]){document.getElementById("ing-kpis").innerHTML="<p style='color:var(--muted);padding:14px'>Sin datos de ingresos para este mes.</p>";document.getElementById("ing-single").style.display="none";return;}
      ingKpisSingle(pv);ingBuildOsFilter("ing-os-filter");ingTable(pv);ingCharts(pv);
    }
  } else {
    document.getElementById("cp-single").style.display=isCompare?"none":"block";
    document.getElementById("cp-compare").style.display=isCompare?"block":"none";
    if(isCompare){cpKpisCompare();cpTrends();cpCmpTable();cpCmpInvoiceFilters();cpCmpInvoiceTable();cpVarPeriodSelectors();cpVarCatOs();cpVarPrestadores();cpVarAltas();}
    else{
      const pv=CP[currentView]?currentView:PERIODOS[PERIODOS.length-1];
      if(!CP[pv]){document.getElementById("cp-kpis").innerHTML="<p style='color:var(--muted);padding:14px'>No hay planilla de costos prestacionales cargada para este mes.</p>";document.getElementById("cp-single").style.display="none";return;}
      cpKpisSingle(pv);cpCharts(pv);cpHeatmap(pv);cpTop(pv);cpPlazos(pv);cpInvoiceFilters(pv);cpInvoiceTable(pv);
    }
  }
}

document.querySelectorAll(".main-tab").forEach(b=>b.addEventListener("click",()=>setTab(b.dataset.tab)));
document.getElementById("cp-search").addEventListener("input",()=>{if(CP[currentView])cpInvoiceTable(currentView);});
document.getElementById("cp-filter-os").addEventListener("change",()=>{if(CP[currentView])cpInvoiceTable(currentView);});
document.getElementById("cp-filter-cat").addEventListener("change",()=>{if(CP[currentView])cpInvoiceTable(currentView);});
document.getElementById("cp-clear").addEventListener("click",()=>{document.getElementById("cp-search").value="";document.getElementById("cp-filter-os").value="";document.getElementById("cp-filter-cat").value="";if(CP[currentView])cpInvoiceTable(currentView);});
document.getElementById("cp-cmp-search").addEventListener("input",()=>cpCmpInvoiceTable());
document.getElementById("cp-cmp-filter-os").addEventListener("change",()=>cpCmpInvoiceTable());
document.getElementById("cp-cmp-filter-cat").addEventListener("change",()=>cpCmpInvoiceTable());
document.getElementById("cp-cmp-clear").addEventListener("click",()=>{document.getElementById("cp-cmp-search").value="";document.getElementById("cp-cmp-filter-os").value="";document.getElementById("cp-cmp-filter-cat").value="";cpCmpInvoiceTable();});
document.getElementById("cp-var-base").addEventListener("change",e=>{cpVarBase=e.target.value;cpVarCatOs();cpVarPrestadores();cpVarAltas();});
document.getElementById("cp-var-comp").addEventListener("change",e=>{cpVarComp=e.target.value;cpVarCatOs();cpVarPrestadores();cpVarAltas();});
document.getElementById("cf-var-base").addEventListener("change",e=>{cfVarBase=e.target.value;cfVarItems();});
document.getElementById("cf-var-comp").addEventListener("change",e=>{cfVarComp=e.target.value;cfVarItems();});
document.getElementById("er-cmp-os-filter").addEventListener("change",()=>erCmpTable());
document.getElementById("cf-comp-filter-item").addEventListener("change",()=>{if(cfCurrentPeriodo)cfComprobantesTable(cfCurrentPeriodo);});
document.getElementById("cf-comp-search").addEventListener("input",()=>{if(cfCurrentPeriodo)cfComprobantesTable(cfCurrentPeriodo);});

document.getElementById("ing-var-base").addEventListener("change",e=>{ingVarBase=e.target.value;ingVarTable();});
document.getElementById("ing-var-comp").addEventListener("change",e=>{ingVarComp=e.target.value;ingVarTable();});

document.getElementById("foot-info").textContent=`${INFO.er_ok||0} meses de Estado de Resultado, ${INFO.cp_ok||0} de Costos Prestacionales`;
buildPeriodButtons();
setView(currentView);
</script>
</body>
</html>